using System; using System.Collections.Generic; using System.Linq; using System.Text.Json; using System.Threading.Tasks; using Microsoft.AspNetCore.Authorization; using ShikshaMitra.Constants.Permissions; using Volo.Abp; using Volo.Abp.Application.Dtos; using Volo.Abp.Application.Services; using Volo.Abp.Domain.Entities; using Volo.Abp.Domain.Repositories;
namespace ShikshaMitra.Students.StudentEnrollments.Admissions;
[Authorize]
public class AdmissionFormAppService(IRepository<AdmissionFormDefinition, Guid> formRepository, IRepository<AdmissionFormSectionDefinition, Guid> sectionRepository, IRepository<AdmissionFormFieldDefinition, Guid> fieldRepository) : ApplicationService, IAdmissionFormAppService
{
	public Task<AdmissionFormDto> PreviewAsync(Guid id) => GetAsync(id);
	private static readonly HashSet<string> ApprovedSystemBindings = new(StringComparer.OrdinalIgnoreCase) { "Applicant.FirstName", "Applicant.MiddleName", "Applicant.LastName", "Applicant.DateOfBirth", "Applicant.Gender", "Guardian.FirstName", "Guardian.LastName", "Guardian.Mobile", "Guardian.Email" };
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.View)] public async Task<PagedResultDto<AdmissionFormDto>> GetListAsync(AdmissionFormListInput input) { var q = await formRepository.GetQueryableAsync(); q = q.Where(x => (!input.Status.HasValue || x.Status == input.Status) && (string.IsNullOrWhiteSpace(input.Search) || x.Name.Contains(input.Search) || x.Code.Contains(input.Search))); var count = await AsyncExecuter.CountAsync(q); var rows = await AsyncExecuter.ToListAsync(q.OrderByDescending(x => x.CreationTime).Skip(input.SkipCount).Take(input.MaxResultCount)); return new(count, rows.Select(x => Map(x, [], [])).ToList()); }
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.View)] public async Task<AdmissionFormDto> GetAsync(Guid id) => await MapAsync(await GetFormAsync(id));
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.Manage)] public async Task<AdmissionFormDto> CreateAsync(CreateUpdateAdmissionFormDto input) { await EnsureCodeAsync(input.Code, null); var form = new AdmissionFormDefinition(GuidGenerator.Create(), CurrentTenant.Id, input.Name, input.Code, input.LayoutType); await formRepository.InsertAsync(form, autoSave: true); await ReplaceChildrenAsync(form.Id, input); return await MapAsync(form); }
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.Manage)] public async Task<AdmissionFormDto> UpdateAsync(Guid id, CreateUpdateAdmissionFormDto input) { var form = await GetFormAsync(id); await EnsureCodeAsync(input.Code, id); form.UpdateDetails(input.Name, input.Code, input.LayoutType); await ReplaceChildrenAsync(id, input); await formRepository.UpdateAsync(form, autoSave: true); return await MapAsync(form); }
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.Manage)] public async Task<AdmissionFormDto> CloneAsync(Guid id) { var source = await GetFormAsync(id); var sections = await GetSectionsAsync(id); var fields = await GetFieldsAsync(id); var versions = await AsyncExecuter.ToListAsync((await formRepository.GetQueryableAsync()).Where(x => x.Code == source.Code)); var clone = new AdmissionFormDefinition(GuidGenerator.Create(), CurrentTenant.Id, source.Name, source.Code, source.LayoutType, versions.Max(x => x.Version) + 1, source.Id); await formRepository.InsertAsync(clone, autoSave: true); var sectionMap = new Dictionary<Guid, Guid>(); foreach (var s in sections) { var newId = GuidGenerator.Create(); sectionMap[s.Id] = newId; await sectionRepository.InsertAsync(new AdmissionFormSectionDefinition(newId, clone.Id, s.Code, s.Name, s.DisplayOrder, s.VisibilityRuleJson)); } foreach (var f in fields) await fieldRepository.InsertAsync(new AdmissionFormFieldDefinition(GuidGenerator.Create(), clone.Id, sectionMap[f.SectionId], f.Code, f.Label, f.FieldType, f.BindingType, f.BindingKey, f.Required, f.ReadOnly, f.DisplayOrder, f.Placeholder, f.HelpText, f.DefaultValue, f.ValidationJson, f.VisibilityRuleJson)); await CurrentUnitOfWork.SaveChangesAsync(); return await MapAsync(clone); }
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.View)] public async Task<AdmissionFormValidationResultDto> ValidateAsync(Guid id) { await GetFormAsync(id); return await ValidateDefinitionAsync(id); }
	[Authorize(ShikshaMitraSubmodulePermissions.Students.AdmissionForms.Publish)] public async Task<AdmissionFormDto> PublishAsync(Guid id) { var form = await GetFormAsync(id); var validation = await ValidateDefinitionAsync(id); if (!validation.IsValid) throw new BusinessException(AdmissionFormErrorCodes.InvalidSystemBinding).WithData("Errors", string.Join("; ", validation.Errors)); form.Publish(CurrentUser.Id); await formRepository.UpdateAsync(form, autoSave: true); return await MapAsync(form); }
	private async Task<AdmissionFormValidationResultDto> ValidateDefinitionAsync(Guid id) { var sections = await GetSectionsAsync(id); var fields = await GetFieldsAsync(id); var result = new AdmissionFormValidationResultDto(); if (sections.Count == 0) result.Errors.Add(AdmissionFormErrorCodes.NoSections); if (sections.GroupBy(x => x.Code, StringComparer.OrdinalIgnoreCase).Any(x => x.Count() > 1)) result.Errors.Add($"DuplicateSectionCode"); if (fields.GroupBy(x => x.Code, StringComparer.OrdinalIgnoreCase).Any(x => x.Count() > 1)) result.Errors.Add(AdmissionFormErrorCodes.DuplicateFieldCode); var known = fields.Select(x => x.Code).ToHashSet(StringComparer.OrdinalIgnoreCase); foreach (var section in sections) ValidateRule(section.VisibilityRuleJson, known, $"Section:{section.Code}", result); foreach (var field in fields) { if (field.BindingType == AdmissionFormBindingType.System && (string.IsNullOrWhiteSpace(field.BindingKey) || !ApprovedSystemBindings.Contains(field.BindingKey))) result.Errors.Add($"{AdmissionFormErrorCodes.InvalidSystemBinding}:{field.Code}"); ValidateRule(field.VisibilityRuleJson, known, field.Code, result); ValidateValidationJson(field.ValidationJson, field.Code, result); } return result; }
	private static void ValidateRule(string? rule, HashSet<string> known, string owner, AdmissionFormValidationResultDto result) { if (string.IsNullOrWhiteSpace(rule)) return; try { using var document = JsonDocument.Parse(rule); var root = document.RootElement; ValidateRuleNode(root, known, owner, result); } catch (JsonException) { result.Errors.Add($"InvalidRuleJson:{owner}"); } }
	private static void ValidateRuleNode(JsonElement node, HashSet<string> known, string owner, AdmissionFormValidationResultDto result) { if (node.TryGetProperty("operator", out var op) && node.TryGetProperty("conditions", out var conditions) && conditions.ValueKind == JsonValueKind.Array) { var operatorName = op.GetString(); if (!string.Equals(operatorName, "ALL", StringComparison.OrdinalIgnoreCase) && !string.Equals(operatorName, "ANY", StringComparison.OrdinalIgnoreCase)) result.Errors.Add($"InvalidRuleOperator:{owner}"); foreach (var condition in conditions.EnumerateArray()) ValidateRuleNode(condition, known, owner, result); return; } if (!node.TryGetProperty("field", out var field) || !known.Contains(field.GetString() ?? string.Empty)) result.Errors.Add($"{AdmissionFormErrorCodes.InvalidRuleReference}:{owner}"); if (!node.TryGetProperty("operator", out var leafOperator) || string.IsNullOrWhiteSpace(leafOperator.GetString())) result.Errors.Add($"InvalidRuleOperator:{owner}"); }
	private static void ValidateValidationJson(string? validation, string code, AdmissionFormValidationResultDto result) { if (string.IsNullOrWhiteSpace(validation)) return; try { using var document = JsonDocument.Parse(validation); if (document.RootElement.ValueKind != JsonValueKind.Object) result.Errors.Add($"InvalidValidationJson:{code}"); } catch (JsonException) { result.Errors.Add($"InvalidValidationJson:{code}"); } }
	private async Task ReplaceChildrenAsync(Guid formId, CreateUpdateAdmissionFormDto input) { foreach (var f in await GetFieldsAsync(formId)) await fieldRepository.DeleteAsync(f, autoSave: false); foreach (var s in await GetSectionsAsync(formId)) await sectionRepository.DeleteAsync(s, autoSave: false); foreach (var section in input.Sections) { var sectionId = section.Id ?? GuidGenerator.Create(); await sectionRepository.InsertAsync(new AdmissionFormSectionDefinition(sectionId, formId, section.Code, section.Name, section.DisplayOrder, section.VisibilityRuleJson), autoSave: false); foreach (var field in section.Fields) { var fieldId = field.Id ?? GuidGenerator.Create(); await fieldRepository.InsertAsync(new AdmissionFormFieldDefinition(fieldId, formId, sectionId, field.Code, field.Label, field.FieldType, field.BindingType, field.BindingKey, field.Required, field.ReadOnly, field.DisplayOrder, field.Placeholder, field.HelpText, field.DefaultValue, field.ValidationJson, field.VisibilityRuleJson), autoSave: false); } } }
	private async Task EnsureCodeAsync(string code, Guid? excludingId) { var normalized = code.Trim().ToUpperInvariant(); var q = await formRepository.GetQueryableAsync(); if (await AsyncExecuter.AnyAsync(q.Where(x => x.Code == normalized && (!excludingId.HasValue || x.Id != excludingId.Value) && x.Status != AdmissionFormStatus.Archived))) throw new BusinessException(AdmissionFormErrorCodes.CodeAlreadyExists); }
	private async Task<AdmissionFormDefinition> GetFormAsync(Guid id) => await formRepository.FindAsync(id) ?? throw new EntityNotFoundException(typeof(AdmissionFormDefinition), id);
	private async Task<List<AdmissionFormSectionDefinition>> GetSectionsAsync(Guid id) => await AsyncExecuter.ToListAsync((await sectionRepository.GetQueryableAsync()).Where(x => x.FormDefinitionId == id).OrderBy(x => x.DisplayOrder));
	private async Task<List<AdmissionFormFieldDefinition>> GetFieldsAsync(Guid id) => await AsyncExecuter.ToListAsync((await fieldRepository.GetQueryableAsync()).Where(x => x.FormDefinitionId == id).OrderBy(x => x.DisplayOrder));
	private async Task<AdmissionFormDto> MapAsync(AdmissionFormDefinition x) => Map(x, await GetSectionsAsync(x.Id), await GetFieldsAsync(x.Id));
	private static AdmissionFormDto Map(AdmissionFormDefinition x, List<AdmissionFormSectionDefinition> sections, List<AdmissionFormFieldDefinition> fields) => new() { Id = x.Id, Name = x.Name, Code = x.Code, Version = x.Version, Status = x.Status, LayoutType = x.LayoutType, ParentVersionId = x.ParentVersionId, PublishedAt = x.PublishedAt, CreationTime = x.CreationTime, CreatorId = x.CreatorId, LastModificationTime = x.LastModificationTime, LastModifierId = x.LastModifierId, Sections = sections.Select(s => new AdmissionFormSectionDto { Id = s.Id, FormDefinitionId = s.FormDefinitionId, Code = s.Code, Name = s.Name, DisplayOrder = s.DisplayOrder, VisibilityRuleJson = s.VisibilityRuleJson, Fields = fields.Where(f => f.SectionId == s.Id).Select(f => new AdmissionFormFieldDto { Id = f.Id, FormDefinitionId = f.FormDefinitionId, SectionId = f.SectionId, Code = f.Code, Label = f.Label, FieldType = f.FieldType, BindingType = f.BindingType, BindingKey = f.BindingKey, Placeholder = f.Placeholder, HelpText = f.HelpText, DefaultValue = f.DefaultValue, Required = f.Required, ReadOnly = f.ReadOnly, DisplayOrder = f.DisplayOrder, ValidationJson = f.ValidationJson, VisibilityRuleJson = f.VisibilityRuleJson }).ToList() }).ToList() };
}
